 const loadDatabaseRows=async(target:Section)=>{
  const supported=["Students","Courses","Batches","Faculty","Analytics","Notifications","Tests","Question Bank","Audit Logs"];
  if(!supported.includes(target)){setDatabaseRows([]);return;}
  const supabase=getSupabaseBrowserClient();if(!supabase){setDatabaseRows([]);return;}
  setLoadingDatabaseRows(true);
  try{
   let rows:string[][]=[];
   if(target==="Students"||target==="Faculty"){
    let query=supabase.from("profiles").select("id,full_name,email,role,is_active,created_at").order("created_at",{ascending:false}).limit(200);
    if(target==="Faculty")query=query.eq("role","faculty");else query=query.eq("role","student");
    const {data,error}=await query;if(error)throw error;
    rows=(data||[]).map(x=>[x.id,x.full_name||"Unnamed learner",x.email||"—",x.role,x.is_active?"Active":"Suspended"]);
   }else if(target==="Courses"){
    const {data,error}=await supabase.from("courses").select("id,title,description,is_published").order("created_at",{ascending:false});if(error)throw error;
    rows=(data||[]).map(x=>[x.id.slice(0,8),x.title,x.description||"—",x.is_published?"Published":"Draft"]);
   }else if(target==="Batches"){
    const {data,error}=await supabase.from("batches").select("id,name,starts_on,ends_on").order("starts_on",{ascending:false});if(error)throw error;
    rows=(data||[]).map(x=>[x.id.slice(0,8),x.name,x.starts_on||"Not scheduled",x.ends_on||"—"]);
   }else if(target==="Analytics"){
    const {data,error}=await supabase.from("student_activity").select("id,student_id,activity_type,created_at").order("created_at",{ascending:false}).limit(200);if(error)throw error;
    rows=(data||[]).map(x=>[x.id.slice(0,8),x.activity_type,x.student_id.slice(0,8),new Date(x.created_at).toLocaleString()]);
   }else if(target==="Notifications"){
    const {data,error}=await supabase.from("announcements").select("id,title,published_at,is_published").order("created_at",{ascending:false});if(error)throw error;
    rows=(data||[]).map(x=>[x.id.slice(0,8),x.title,x.published_at?new Date(x.published_at).toLocaleString():"Not published",x.is_published?"Published":"Draft"]);
   }else if(target==="Audit Logs"){
    const {data,error}=await supabase.from("admin_audit_logs").select("id,actor_id,target_user_id,action,details,created_at").order("created_at",{ascending:false}).limit(200);if(error)throw error;
    rows=(data||[]).map(x=>[x.id.slice(0,8),x.action,x.target_user_id?.slice(0,8)||"—",new Date(x.created_at).toLocaleString("en-IN")]);
   }else if(target==="Tests"){
    const {data,error}=await supabase.from("assessments").select("id,title,kind,is_published").order("created_at",{ascending:false});if(error)throw error;
    rows=(data||[]).map(x=>[x.id.slice(0,8),x.title,x.kind,x.is_published?"Published":"Draft"]);
   }else if(target==="Question Bank"){
    const {data,error}=await supabase.from("questions").select("id,question_en,topic,difficulty").order("created_at",{ascending:false}).limit(200);if(error)throw error;
    rows=(data||[]).map(x=>[x.id.slice(0,8),x.question_en,x.topic||"—",x.difficulty]);
   }
   setDatabaseRows(rows);
  }catch(error){setNotice(error instanceof Error?error.message:"Unable to load live records.");setDatabaseRows([]);}
  finally{setLoadingDatabaseRows(false);}
 };
 const toggleAccountAccess=async(userId:string,isActive:boolean,accountType:"student"|"faculty")=>{
  const label=accountType==="faculty"?"faculty":"student";
  if(!window.confirm(isActive?`Suspend this ${label} account? The user will lose platform access.`:`Restore access for this ${label} account?`))return;
  const supabase=getSupabaseBrowserClient();if(!supabase)throw new Error("Supabase client is not configured.");
  const {data:{user},error:userError}=await supabase.auth.getUser();
  if(userError||!user){setNotice("Your admin session could not be verified. Please sign in again.");return;}
  if(user.id===userId&&isActive){setNotice("You cannot suspend your own active admin session.");return;}
  const {error}=await supabase.from("profiles").update({is_active:!isActive}).eq("id",userId).eq("role",accountType);
  if(error){setNotice(error.message);return;}
  setNotice(isActive?`${accountType==="faculty"?"Faculty":"Student"} account suspended.`:`${accountType==="faculty"?"Faculty":"Student"} account access restored.`);
  await loadDatabaseRows(accountType==="faculty"?"Faculty":"Students");
 };
